import type { Decimal } from '../shared/decimal.ts';
import { MissingParameterError } from '../exceptions/MissingParameterError.ts';

export const ParameterCode = {
  MAX_REPORT_DAYS: 'DIAS_MAX_DENUNCIA',
  MAX_REPORT_DAYS_LIFE: 'DIAS_MAX_DENUNCIA_VIDA',
  MINIMUM_DEDUCTIBLE: 'DEDUCIBLE_MINIMO',
  VIP_DEDUCTIBLE_DISCOUNT_PCT: 'PCT_DESCUENTO_DED_VIP',
  VIP_ARREARS_TOLERANCE: 'TOLERANCIA_MORA_VIP',
  MAX_ANNUAL_CLAIMS: 'MAX_SINIESTROS_ANUAL',
  CLAIM_FREQUENCY_PENALTY_PCT: 'PCT_PENALIZACION_SINIEST',
  WITHHOLDING_THRESHOLD: 'UMBRAL_RETENCION',
  WITHHOLDING_RATE_PCT: 'TASA_RETENCION',
  AUTO_APPROVAL_LIMIT: 'TOPE_AUTO_APROBACION',
  FRAUD_ALERT_DAYS: 'DIAS_ALERTA_FRAUDE',
  FRAUD_ALERT_PCT: 'PCT_ALERTA_FRAUDE',
  INFLATION_FACTOR: 'FACTOR_INFLACION',
} as const;

/**
 * Parámetros de negocio tipados. Cada lectura es perezosa, como fn_param_num del legacy:
 * solo falla (ORA-20010) el parámetro que realmente se necesita.
 * @rule R-023
 */
export class BusinessParameters {
  private readonly values: ReadonlyMap<string, Decimal>;

  constructor(values: ReadonlyMap<string, Decimal>) {
    this.values = values;
  }

  /** @rule R-023 */
  has(code: string): boolean {
    return this.values.has(code);
  }

  /** @rule R-023 */
  private readRequired(code: string): Decimal {
    const value = this.values.get(code);
    if (value === undefined) {
      throw new MissingParameterError(code);
    }
    return value;
  }

  get maxReportDays(): Decimal {
    return this.readRequired(ParameterCode.MAX_REPORT_DAYS);
  }

  get maxReportDaysLife(): Decimal {
    return this.readRequired(ParameterCode.MAX_REPORT_DAYS_LIFE);
  }

  get minimumDeductible(): Decimal {
    return this.readRequired(ParameterCode.MINIMUM_DEDUCTIBLE);
  }

  get vipDeductibleDiscountPct(): Decimal {
    return this.readRequired(ParameterCode.VIP_DEDUCTIBLE_DISCOUNT_PCT);
  }

  get vipArrearsTolerance(): Decimal {
    return this.readRequired(ParameterCode.VIP_ARREARS_TOLERANCE);
  }

  get maxAnnualClaims(): Decimal {
    return this.readRequired(ParameterCode.MAX_ANNUAL_CLAIMS);
  }

  get claimFrequencyPenaltyPct(): Decimal {
    return this.readRequired(ParameterCode.CLAIM_FREQUENCY_PENALTY_PCT);
  }

  get withholdingThreshold(): Decimal {
    return this.readRequired(ParameterCode.WITHHOLDING_THRESHOLD);
  }

  get withholdingRatePct(): Decimal {
    return this.readRequired(ParameterCode.WITHHOLDING_RATE_PCT);
  }

  get autoApprovalLimit(): Decimal {
    return this.readRequired(ParameterCode.AUTO_APPROVAL_LIMIT);
  }

  get fraudAlertDays(): Decimal {
    return this.readRequired(ParameterCode.FRAUD_ALERT_DAYS);
  }

  get fraudAlertPct(): Decimal {
    return this.readRequired(ParameterCode.FRAUD_ALERT_PCT);
  }
}
